import { z } from 'zod'

/** Opaque id from the host app (passed as ?deviceId=) or a UUID generated by the page itself */
export const deviceIdSchema = z.string().trim().min(8).max(128).regex(/^[\w.:-]+$/)

export const purchaseBodySchema = z.object({
  offerId: z.string().min(1).max(64),
  deviceId: deviceIdSchema,
  idempotencyKey: z.uuid(),
})

export const restoreBodySchema = z.object({
  deviceId: deviceIdSchema,
})

/**
 * Test hooks for reviewers: ?simulate=error|slow on the page is forwarded to the API,
 * so error and loading states can be seen on the deployed version without breaking anything.
 */
export async function applySimulation(simulate: unknown, message: string) {
  if (simulate === 'slow') await new Promise(resolve => setTimeout(resolve, 2000))
  if (simulate === 'error') throw createError({ statusCode: 503, statusMessage: message })
}
